n=28
G=[[0]*n for _ in range(n)]
# lattice separators
for i in [4,9,14,19,24]:
    for j in range(n): G[i][j]=8; G[j][i]=8
# cell coloring based on connected marker alignments
for br in range(6):
 for bc in range(6):
  c2=(br==1 and 0<=bc<=4) or (bc==0 and 1<=br<=3)
  c3=(bc==2 and 0<=br<=4)
  color=6 if c2 and c3 else 2 if c2 else 3 if c3 else 0
  if color:
   r0=br*5; c0=bc*5
   for r in range(r0,min(r0+4,n)):
    for c in range(c0,min(c0+4,n)):
     G[r][c]=color
print(__import__('json').dumps(G))
